<script setup lang="ts">import{onMounted,ref}from'vue';import{NButton,NEmpty,NSkeleton}from'naive-ui';import{api}from'../api';const stats=ref<any>(null);onMounted(async()=>stats.value=await api.get('/stats/overview'))</script>
